    }

    #[test]
    fn all_seven_tasks_map_to_production_harnesses() {
        for task in BENCHMARK_TASKS {
            let harness = campaign_task_harness(task.id).expect("harness");
            if matches!(
                task.kind,
                BenchmarkTaskKind::RuntimeInteraction | BenchmarkTaskKind::VisualEvaluation
            ) {
                assert_eq!(harness, CampaignTaskHarness::ProductionRuntimeDebug);
            }
        }
    }

    #[test]
    fn runtime_characterization_keeps_one_representation_and_two_runtime_identities() {
        let mut plan = plan();
        plan.candidates.truncate(1);
        plan.runtime_identities = vec![
            runtime(CampaignExecutionEnvironment::WindowsNative),
            runtime(CampaignExecutionEnvironment::Wsl2Linux),
        ];
        plan.comparison_class = CampaignComparisonClass::RuntimeCharacterization;
        assert!(plan.validate().is_ok());
        let schedule = plan.schedule().expect("schedule");
        assert_eq!(schedule[0].candidate_index, 0);
        assert_eq!(schedule[1].candidate_index, 0);
        assert_ne!(schedule[0].execution_environment, schedule[1].execution_environment);
    }

    #[test]
    fn model_schedule_is_deterministic_and_interleaves_candidates() {
        let plan = plan();
        let first = plan.schedule().expect("schedule");
        let second = plan.schedule().expect("same schedule");
        assert_eq!(first, second);
        assert_eq!(first[0].candidate_index, 0);
        assert_eq!(first[1].candidate_index, 1);
    }

    #[test]
    fn acquisition_preflight_ignores_runtime_environment_identity() {
        let campaign = BenchmarkCampaign::new(plan()).expect("campaign");
        let installed = installed(&campaign.plan);
        assert!(campaign.preflight(&installed).expect("preflight").missing.is_empty());
    }

    #[test]
    fn measured_failure_is_never_retried_as_pre_measurement_noise() {
        let mut campaign = BenchmarkCampaign::new(plan()).expect("campaign");
        let installed = installed(&campaign.plan);
        campaign.start(&installed).expect("start");
        let request = campaign.begin_next_run().expect("next").expect("request");
        campaign.mark_measurement_started(&request).expect("measure");
        assert!(campaign.record_pre_measurement_failure(&request).is_err());
        campaign
            .fail_measured_run(&request, CampaignFailureKind::ValidationFailure)
            .expect("failure retained");
        assert_eq!(campaign.runs[0].status, CampaignRunStatus::Failed);
    }

    #[test]
    fn completed_record_gets_exact_campaign_execution_identity() {
        let mut campaign = BenchmarkCampaign::new(plan()).expect("campaign");
        let installed = installed(&campaign.plan);
        campaign.start(&installed).expect("start");
        let request = campaign.begin_next_run().expect("next").expect("request");
        campaign.mark_measurement_started(&request).expect("measure");
        let evidence = record(&request, &campaign.plan);
        campaign.complete_run(&request, evidence).expect("complete");
        let execution = campaign.runs[0]
            .record
            .as_ref()
            .and_then(|record| record.identity.execution.as_ref())
            .expect("execution");
        assert_eq!(execution.execution_environment, "windows_native");
        assert_eq!(execution.fixture_instance_id, request.fixture.instance_id);
    }
